    35	    public long inserir(String cpf, Instant criadoEm, Resumo resumo, List<ItemPedido> itens) {
    36	        KeyHolder chave = new GeneratedKeyHolder();
    37	        jdbc.sql("INSERT INTO pedido (cpf, situacao, criado_em, resumo) VALUES (?, ?, ?, ?)")
    38	                .param(cpf).param(SituacaoPedido.AGUARDANDO_PAGAMENTO.name()).param(paraBanco(criadoEm))
    39	                .param(json.writeValueAsString(resumo))
    40	                .update(chave, "id");
    41	        long id = chave.getKeyAs(Number.class).longValue();
    42	        for (int i = 0; i < itens.size(); i++) {
    43	            jdbc.sql("INSERT INTO item_pedido (pedido_id, sku, quantidade, posicao) VALUES (?, ?, ?, ?)")
    44	                    .param(id).param(itens.get(i).sku()).param(itens.get(i).quantidade()).param(i).update();
    45	        }
    46	        return id;
    47	    }
