    35	@Component
    36	public class CalculadoraResumo {
    38	    private static final Pattern CPF = Pattern.compile("\\d{11}");
    39	    private static final Pattern CEP = Pattern.compile("\\d{8}");
    41	    private final ProdutoRepositorio produtos;
    42	    private final NiveisClube niveis;
    43	    private final ModalidadesEntrega modalidades;
    44	    private final Cupons cupons;
