    48	            Cupons cupons, FormasPagamento formas) {
    49	        this.produtos = produtos;
    50	        this.niveis = niveis;
    51	        this.modalidades = modalidades;
    52	        this.cupons = cupons;
    53	        this.formas = formas;
    54	    }
    56	    public Checkout calcular(JsonNode dados) {
    57	        if (dados == null || !dados.isObject()) {
    58	            throw ErroNegocio.invalido("PEDIDO_INVALIDO");
    59	        }
    60	        JsonNode cliente = dados.get("cliente");
    61	        String cpf = cliente != null && cliente.isObject() ? texto(cliente, "cpf") : null;
    62	        String email = cliente != null && cliente.isObject() ? texto(cliente, "email") : null;
    63	        List<ItemSolicitado> solicitados = lerItens(dados.get("itens"));
    64	        if (cpf == null || !CPF.matcher(cpf).matches() || email == null || email.isBlank()) {
    65	            throw ErroNegocio.invalido("PEDIDO_INVALIDO");
    66	        }
    68	        List<ItemCarrinho> itens = conferirCatalogo(solicitados);
    69	        BigDecimal subtotal = Dinheiro.centavos(itens.stream().map(ItemCarrinho::valor).reduce(BigDecimal.ZERO, BigDecimal::add));
    70	        BigDecimal peso = itens.stream().map(ItemCarrinho::peso).reduce(BigDecimal.ZERO, BigDecimal::add);
    72	        NivelClube nivel = niveis.buscar(texto(dados, "nivelClube"))
    73	                .orElseThrow(() -> ErroNegocio.invalido("NIVEL_CLUBE_INVALIDO"));
    74	        Regiao regiao = Optional.ofNullable(texto(dados, "regiao")).flatMap(Regiao::deCodigo)
    75	                .orElseThrow(() -> ErroNegocio.invalido("REGIAO_INVALIDA"));
    76	        String cep = texto(dados, "cep");
    77	        if (cep == null || !CEP.matcher(cep).matches()) {
    78	            throw ErroNegocio.invalido("CEP_INVALIDO");
    79	        }
    80	        ModalidadeEntrega modalidade = modalidades.buscar(texto(dados, "modalidadeEntrega"))
    81	                .orElseThrow(() -> ErroNegocio.invalido("MODALIDADE_INVALIDA"));
    82	        CotacaoEntrega cotacao = modalidade.cotar(new ContextoEntrega(cep, regiao, peso, subtotal));
    83	        BigDecimal frete = nivel.isentaFrete(modalidade) ? Dinheiro.ZERO : Dinheiro.centavos(cotacao.frete());
    85	        Optional<Cupom> cupom = lerCupom(dados);
    86	        BigDecimal descontoCupom = cupom
    87	                .map(c -> Dinheiro.centavos(c.desconto(new ContextoCupom(cpf, itens, subtotal, modalidade, frete))))
    88	                .orElse(Dinheiro.ZERO);
    90	        FormaPagamento forma = formas.buscar(texto(dados, "formaPagamento"))
    91	                .orElseThrow(() -> ErroNegocio.invalido("FORMA_PAGAMENTO_INVALIDA"));
    92	        int parcelas = lerParcelas(dados.get("parcelas"));
    93	        if (!forma.aceitaParcelas(parcelas)) {
    94	            throw ErroNegocio.invalido("PARCELAMENTO_INVALIDO");
    95	        }
    97	        BigDecimal seguro = regiao.seguro(subtotal);
    98	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
    99	        if (!forma.atende(totalPedido)) {
   100	            throw ErroNegocio.invalido("FORMA_PAGAMENTO_INDISPONIVEL");
   101	        }
   102	        ResultadoPagamento pagamento = forma.calcular(totalPedido, parcelas, cupom.isPresent());
   103	        BigDecimal totalFinal = Dinheiro.centavos(pagamento.totalFinal());
   105	        Resumo resumo = new Resumo(subtotal, descontoCupom, frete, cotacao.prazoDias(), seguro,
   106	                totalFinal.subtract(totalPedido), totalFinal, pagamento.parcelas(),
   107	                Dinheiro.centavos(pagamento.valorParcela()), Dinheiro.centavos(nivel.credito(subtotal)),
   108	                nivel.ganhaBrinde(subtotal));
   109	        return new Checkout(cpf, email, itens, resumo);
   110	    }
   112	    private record ItemSolicitado(String sku, int quantidade) {
   113	    }
   115	    private static List<ItemSolicitado> lerItens(JsonNode itens) {
   116	        if (itens == null || !itens.isArray() || itens.isEmpty()) {
   117	            throw ErroNegocio.invalido("PEDIDO_INVALIDO");
   118	        }
   119	        List<ItemSolicitado> lidos = new ArrayList<>();
   120	        Set<String> skus = new HashSet<>();
   121	        for (JsonNode item : itens.values()) {
   122	            String sku = item.isObject() ? texto(item, "sku") : null;
   123	            JsonNode quantidade = item.isObject() ? item.get("quantidade") : null;
   124	            if (sku == null || sku.isBlank() || !skus.add(sku) || quantidade == null || !quantidade.isIntegralNumber()
   125	                    || !quantidade.canConvertToInt() || quantidade.intValue() <= 0) {
   126	                throw ErroNegocio.invalido("PEDIDO_INVALIDO");
   127	            }
   128	            lidos.add(new ItemSolicitado(sku, quantidade.intValue()));
   129	        }
   130	        return lidos;
   131	    }
   133	    private List<ItemCarrinho> conferirCatalogo(List<ItemSolicitado> solicitados) {
   134	        List<ItemCarrinho> itens = new ArrayList<>();
   135	        for (ItemSolicitado solicitado : solicitados) {
   136	            Produto produto = produtos.buscar(solicitado.sku())
   137	                    .orElseThrow(() -> ErroNegocio.invalido("PRODUTO_INEXISTENTE"));
   138	            itens.add(new ItemCarrinho(produto, solicitado.quantidade()));
   139	        }
   140	        if (itens.stream().anyMatch(item -> item.produto().foraDeLinha())) {
   141	            throw ErroNegocio.invalido("PRODUTO_FORA_DE_LINHA");
   142	        }
   143	        if (itens.stream().anyMatch(item -> item.produto().estoque() < item.quantidade())) {
   144	            throw ErroNegocio.invalido("ESTOQUE_INSUFICIENTE");
   145	        }
   146	        return itens;
   147	    }
   149	    private Optional<Cupom> lerCupom(JsonNode dados) {
   150	        JsonNode codigo = dados.get("cupom");
   151	        if (codigo == null || codigo.isNull() || (codigo.isString() && codigo.stringValue().isEmpty())) {
   152	            return Optional.empty();
   153	        }
   154	        if (!codigo.isString()) {
   155	            throw ErroNegocio.invalido("CUPOM_INVALIDO");
   156	        }
   157	        return Optional.of(cupons.buscar(codigo.stringValue()).orElseThrow(() -> ErroNegocio.invalido("CUPOM_INVALIDO")));
   158	    }
   160	    private static int lerParcelas(JsonNode parcelas) {
   161	        if (parcelas == null || parcelas.isNull()) {
   162	            return 1;
   163	        }
   164	        if (!parcelas.isIntegralNumber() || !parcelas.canConvertToInt()) {
   165	            throw ErroNegocio.invalido("PARCELAMENTO_INVALIDO");
   166	        }
   167	        return parcelas.intValue();
   168	    }
   170	    private static String texto(JsonNode no, String campo) {
   171	        JsonNode valor = no.get(campo);
   172	        return valor != null && valor.isString() ? valor.stringValue() : null;
   173	    }
   174	}
